#include "dk1/player_live_runtime.h"
#include <string.h>
void dk1_player_live_init(Dk1PlayerLiveRuntime*r){if(!r)return;memset(r,0,sizeof(*r));r->state=1u;r->handler_pc=dk1_player_state_handler_pc(1u);}
void dk1_player_live_step(Dk1PlayerLiveRuntime*r,Dk1PlayerPreviewRuntime*p,Dk1PlayerTerrainRuntime*t,uint16_t held,uint16_t pressed){Dk1PlayerStateFrame f;Dk1PlayerStateInputs in={0};Dk1PlayerStateResult out;uint16_t old_x;int16_t old_y;if(!r||!p)return;old_x=p->motion.world_x;old_y=p->motion.world_y;dk1_player_preview_apply_input(p,held,pressed);if(p->airborne){r->state=11u;memset(&f,0,sizeof(f));f.state=11u;f.flags_0579=0;f.world_x=(int16_t)p->motion.world_x;f.world_y=p->motion.world_y;f.velocity_x=p->motion.velocity_x;f.velocity_y=p->motion.velocity_y;if(dk1_player_state_step_compact(&f,in,&out)){p->motion.velocity_y=f.velocity_y;r->required_calls=out.required_calls;r->used_local_semantics=true;r->local_steps++;}}else{r->state=1u;r->required_calls=0;r->used_local_semantics=false;r->plan_steps++;}dk1_player_preview_integrate(p);if(t&&t->ready)dk1_player_terrain_resolve_motion(t,p,old_x,old_y);else dk1_player_preview_resolve_floor(p,true,p->floor_y,p->floor_attributes);if(!p->airborne)r->state=1u;r->handler_pc=dk1_player_state_handler_pc(r->state);r->dispatches++;}
